"""Applies the 'policy start date on the case form' feature directly,
bypassing git am/apply entirely (works regardless of CRLF/LF or copy-paste
mangling). Run from the repo root: python apply_policy_start_date_feature.py
"""
import io


def edit(path, replacements):
    with io.open(path, "r", encoding="utf-8", newline=None) as f:
        content = f.read()
    for old, new in replacements:
        if old not in content:
            raise SystemExit(f"ERROR: expected text not found in {path}:\n{old!r}")
        content = content.replace(old, new, 1)
    with io.open(path, "w", encoding="utf-8", newline="\n") as f:
        f.write(content)
    print(f"Updated {path}")


